mapper.select:
SELECT STUDENT.STD_NO, STUDENT.STD_NAME, STUDENT.STD_ID, STUDENT.STD_TELNO, STUDENT.STD_ADDRESS, STUDENT.PRO_NO, PROFESSOR.PRO_NAME
FROM STUDENT LEFT JOIN PROFESSOR ON STUDENT.PRO_NO = PROFESSOR.PRO_NO
WHERE STUDENT.STD_NO = #{stdNo}

SELECT B.* FROM( SELECT ROWNUM RNUM, A.* FROM( SELECT S.SUB_CD ,S.SUB_GUBUN ,S.SUB_NAME ,S.SUB_CREDIT FROM SUBJECT S LEFT JOIN CLASS C ON S.SUB_CD = C.SUB_CD AND C.STD_NO = #{stNo1} WHERE C.SUB_CD IS NULL ) A
) B
WHERE RNUM >= #{paging.startRow} AND RNUM <= #{paging.endRow}

